'use strict';

/* ── theme-toggle.js ── */
/* ── MaterialDocs: Theme Toggle ──
   Dark mode toggle with system preference detection and localStorage persistence. */
(function() {
  var toggle = document.getElementById('md-theme-toggle');
  if (!toggle) return;

  // Apply saved preference before paint
  var saved = localStorage.getItem('md-theme');
  if (saved) document.documentElement.setAttribute('data-theme', saved);

  toggle.addEventListener('click', function() {
    var current = document.documentElement.getAttribute('data-theme');
    var isDark = current === 'dark' ||
      (!current && window.matchMedia('(prefers-color-scheme: dark)').matches);
    var next = isDark ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('md-theme', next);
  });

  // The icon itself is swapped by CSS off the resolved theme — see the
  // .md-icon-light / .md-icon-dark rules in the generated token stylesheet.
})();


/* ── sidebar.js ── */
/* ── MaterialDocs: Sidebar ──
   Collapsible nav sections and mobile hamburger menu. */
(function() {
  // ── Collapsible sections ──
  var titles = document.querySelectorAll('.md-nav-section-title');
  for (var i = 0; i < titles.length; i++) {
    (function(title) {
      var section = title.parentElement;
      var key = 'md-nav-' + title.textContent.trim().toLowerCase().replace(/\s+/g, '-');
      // The build sets the initial state from `collapselevel`; a reader's own
      // choice overrides it, except that the section holding the current page
      // is never hidden.
      var saved = localStorage.getItem(key);
      if (saved === 'collapsed' && !section.querySelector('.md-nav-active')) {
        section.classList.add('md-nav-collapsed');
      } else if (saved === 'expanded') {
        section.classList.remove('md-nav-collapsed');
      }
      title.style.cursor = 'pointer';
      title.setAttribute('role', 'button');
      title.setAttribute('aria-expanded', !section.classList.contains('md-nav-collapsed'));
      title.addEventListener('click', function() {
        var collapsed = section.classList.toggle('md-nav-collapsed');
        title.setAttribute('aria-expanded', !collapsed);
        localStorage.setItem(key, collapsed ? 'collapsed' : 'expanded');
      });
    })(titles[i]);
  }

  // ── Mobile hamburger ──
  var hamburger = document.getElementById('md-hamburger');
  // Multi-page sites have .md-sidebar; single-page sites only have .md-toc
  var sidebar = document.querySelector('.md-sidebar');
  var toc = document.querySelector('.md-toc');
  var panel = sidebar || toc;

  if (hamburger && panel) {
    // Create scrim overlay
    var scrim = document.createElement('div');
    scrim.className = 'md-sidebar-scrim';
    document.body.appendChild(scrim);

    // If using TOC as the mobile panel, add the sidebar positioning classes
    if (!sidebar && toc) {
      toc.classList.add('md-mobile-nav');
    }

    function openPanel() {
      panel.classList.add('md-sidebar-open');
      scrim.classList.add('active');
      hamburger.setAttribute('aria-expanded', 'true');
    }

    function closePanel() {
      panel.classList.remove('md-sidebar-open');
      scrim.classList.remove('active');
      hamburger.setAttribute('aria-expanded', 'false');
    }

    hamburger.addEventListener('click', function() {
      if (panel.classList.contains('md-sidebar-open')) {
        closePanel();
      } else {
        openPanel();
      }
    });

    // Close when clicking scrim
    scrim.addEventListener('click', closePanel);

    // Close when clicking a link inside the panel
    panel.addEventListener('click', function(e) {
      if (e.target.tagName === 'A') {
        closePanel();
      }
    });
  }
})();


/* ── copy.js ── */
/* ── MaterialDocs: Copy Code ──
   Clipboard copy for code blocks with visual feedback. */
(function() {
  document.addEventListener('click', function(e) {
    var btn = e.target.closest('.md-copy-btn');
    if (!btn) return;
    var block = btn.closest('.md-code-block');
    if (!block) return;
    // An @repl block holds one <code> per input and output
    var codes = block.querySelectorAll('pre > code');
    if (!codes.length) return;

    var text = Array.prototype.map.call(codes, function(c) { return c.textContent; }).join('\n');
    if (navigator.clipboard) {
      navigator.clipboard.writeText(text).then(function() {
        showCopied(btn);
      });
    } else {
      // Fallback for older browsers / non-HTTPS
      var ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); showCopied(btn); }
      catch(err) { /* silently fail */ }
      document.body.removeChild(ta);
    }
  });

  function showCopied(btn) {
    btn.classList.add('copied');
    setTimeout(function() { btn.classList.remove('copied'); }, 1500);
  }
})();


/* ── toc.js ── */
/* ── MaterialDocs: TOC Scroll Spy ──
   Highlights the active heading in the right-rail table of contents.
   Listens on .md-content (the scrollable content column). */
(function() {
  var links = document.querySelectorAll('.md-toc-link');
  if (!links.length) return;

  var content = document.querySelector('.md-content');
  if (!content) return;

  // Build heading list from TOC hrefs
  var headings = [];
  for (var i = 0; i < links.length; i++) {
    var href = links[i].getAttribute('href');
    if (href && href.charAt(0) === '#') {
      var el = document.getElementById(href.slice(1));
      if (el) headings.push({ el: el, link: links[i] });
    }
  }
  if (!headings.length) return;

  var active = null;
  var OFFSET = 80; // pixels below top to trigger

  function update() {
    var scrollTop = content.scrollTop;
    var current = null;
    for (var i = 0; i < headings.length; i++) {
      // offsetTop is relative to offsetParent; subtract content's offset
      var top = headings[i].el.offsetTop - content.offsetTop;
      if (top - OFFSET <= scrollTop) {
        current = headings[i];
      }
    }
    // At bottom of scrollable area, activate last heading
    if (content.scrollTop + content.clientHeight >= content.scrollHeight - 2) {
      current = headings[headings.length - 1];
    }
    if (current !== active) {
      if (active) active.link.classList.remove('active');
      if (current) current.link.classList.add('active');
      active = current;
    }
  }

  // Throttled scroll handler on the content column
  var ticking = false;
  content.addEventListener('scroll', function() {
    if (!ticking) {
      requestAnimationFrame(function() { update(); ticking = false; });
      ticking = true;
    }
  }, { passive: true });

  // Smooth scroll on TOC click — scroll only the content column
  for (var j = 0; j < links.length; j++) {
    links[j].addEventListener('click', function(e) {
      var href = this.getAttribute('href');
      if (href && href.charAt(0) === '#') {
        var target = document.getElementById(href.slice(1));
        if (target) {
          e.preventDefault();
          // Manually compute scroll position within content column
          // to avoid scrollIntoView nudging other containers
          var targetTop = target.offsetTop - content.offsetTop;
          content.scrollTo({ top: targetTop, behavior: 'smooth' });
          history.replaceState(null, '', href);
        }
      }
    });
  }

  // Intercept all hash-link clicks within content to prevent body scroll
  content.addEventListener('click', function(e) {
    var link = e.target.closest('a[href^="#"]');
    if (!link) return;
    var id = link.getAttribute('href').slice(1);
    var target = document.getElementById(id);
    if (target) {
      e.preventDefault();
      var targetTop = target.offsetTop - content.offsetTop;
      content.scrollTo({ top: targetTop, behavior: 'smooth' });
      history.replaceState(null, '', '#' + id);
    }
  });

  update(); // initial state
})();


